/* OpenIC-assets-5.js - part 5 of 7 of the game icons for Open IC Creator's in-game window: icon sheets as data: URIs. OpenIC.iss loads the parts into the window's page
   (ISXOgreX.UI:EvalFile) one at a time once the window is open. Built by tools/build-window.js. The icons are
   EverQuest II's own art (Daybreak Game Company). */
(function () {
  var L = window.OpenIC_LIB;
  if (!L || !L.IC) return;
  var st = document.getElementById('openic-icon-sheets-5');
  if (!st) { st = document.createElement('style'); st.id = 'openic-icon-sheets-5'; (document.head || document.body).appendChild(st); }
  st.textContent = ".oic-sp-22{background-image:url(data:image/png;base64,);}\n.oic-sp-23{background-image:url(data:image/png;base64,);}\n.oic-sp-24{background-image:url(data:image/png;base64,);}\n.oic-sp-25{background-image:url(data:image/png;base64,);}\n.oic-sp-26{background-image:url(data:image/png;base64,);}\n.oic-sp-27{background-image:url(data:image/png;base64,);}\n";
  if (typeof window.ogreUISet === 'function') window.ogreUISet('openic', 'openic-assets-got', '5/7');
})();
